/**
 * copyUrlSession — the "asked once per session" flag for the external-link
 * copy confirmation (ticket #1134).
 *
 * The external-link modal confirms the FIRST copy of an external URL per
 * browser session; after that, later copies skip the confirm and go straight
 * to the clipboard. That one bit of state lives in sessionStorage (per-tab,
 * cleared when the tab closes — deliberately NOT localStorage, so the
 * confirmation doesn't persist forever across visits). These wrappers guard the
 * "sessionStorage may throw in private mode / on quota" case like studio-mfe's
 * safeStorage, so a blocked read reads as not-confirmed (re-ask, the safe
 * default) and a blocked write is a best-effort no-op.
 */

/** sessionStorage key holding the once-per-session copy confirmation. */
export const COPY_URL_CONFIRMED_KEY = "monitor.search.copyUrlConfirmed";

/** True once the user has confirmed an external-URL copy this session. */
export function hasConfirmedCopyThisSession(): boolean {
  try {
    return sessionStorage.getItem(COPY_URL_CONFIRMED_KEY) === "1";
  } catch {
    // sessionStorage unavailable (private mode / quota) — re-ask (safe default).
    return false;
  }
}

/** Remember that the user confirmed an external-URL copy for this session. */
export function markCopyConfirmedThisSession(): void {
  try {
    sessionStorage.setItem(COPY_URL_CONFIRMED_KEY, "1");
  } catch {
    // Best effort: a blocked write just means we re-ask next time.
  }
}


