/**
 * countries — the COMPLETE ISO-3166-1 alpha-2 country list backing the Search
 * country-scope control (ticket #1135; completed from the old hand-curated
 * subset to the full table in #2808/#1135).
 *
 * Each entry is a 2-letter LOWERCASE code (fed to Serper's `gl` param, which
 * lower-cases it anyway, and later GDELT's `sourcecountry`) paired with its
 * flag emoji. The list is the full set of officially-assigned ISO-3166-1
 * alpha-2 codes (~249), sorted by code, so the scope menu is an exhaustive
 * registry — a hand-curated subset dropped real countries (Panama and others
 * were missing). "Worldwide" (undefined code) remains the cost-safe default
 * handled by the caller.
 *
 * Display names are resolved at RENDER time via `Intl.DisplayNames(locale,
 * { type: "region" })` so the same code shows the country's name in whatever
 * locale the UI is in — never a hardcoded English label that would go stale
 * across the 11 locales.
 */

/** One selectable country: an ISO-3166-1 alpha-2 code + its flag emoji. */
export interface Country {
  /** ISO-3166-1 alpha-2, lowercase (e.g. "us"). */
  readonly code: string;
  /** The regional-indicator flag emoji for `code`. */
  readonly flag: string;
}

/**
 * flagEmoji — map a 2-letter country code to its flag emoji by offsetting each
 * ASCII letter into the Unicode regional-indicator block (A → U+1F1E6). Case-
 * insensitive; assumes a 2-letter alpha input (the ISO code list below).
 */
export function flagEmoji(code: string): string {
  return code
    .toUpperCase()
    .replace(/[A-Z]/g, (ch) => String.fromCodePoint(0x1f1e6 + ch.charCodeAt(0) - 65));
}

// The complete set of officially-assigned ISO-3166-1 alpha-2 codes, lowercase
// and sorted by code. Names are NOT listed here — they resolve at render time
// via Intl.DisplayNames, so this table never goes stale across the 11 locales.
// Flags are derived programmatically (see flagEmoji), not literal-ed, so a code
// and its flag can never drift apart.
const CODES: readonly string[] = [
  "ad", "ae", "af", "ag", "ai", "al", "am", "ao", "aq", "ar", "as", "at", "au",
  "aw", "ax", "az", "ba", "bb", "bd", "be", "bf", "bg", "bh", "bi", "bj", "bl",
  "bm", "bn", "bo", "bq", "br", "bs", "bt", "bv", "bw", "by", "bz", "ca", "cc",
  "cd", "cf", "cg", "ch", "ci", "ck", "cl", "cm", "cn", "co", "cr", "cu", "cv",
  "cw", "cx", "cy", "cz", "de", "dj", "dk", "dm", "do", "dz", "ec", "ee", "eg",
  "eh", "er", "es", "et", "fi", "fj", "fk", "fm", "fo", "fr", "ga", "gb", "gd",
  "ge", "gf", "gg", "gh", "gi", "gl", "gm", "gn", "gp", "gq", "gr", "gs", "gt",
  "gu", "gw", "gy", "hk", "hm", "hn", "hr", "ht", "hu", "id", "ie", "il", "im",
  "in", "io", "iq", "ir", "is", "it", "je", "jm", "jo", "jp", "ke", "kg", "kh",
  "ki", "km", "kn", "kp", "kr", "kw", "ky", "kz", "la", "lb", "lc", "li", "lk",
  "lr", "ls", "lt", "lu", "lv", "ly", "ma", "mc", "md", "me", "mf", "mg", "mh",
  "mk", "ml", "mm", "mn", "mo", "mp", "mq", "mr", "ms", "mt", "mu", "mv", "mw",
  "mx", "my", "mz", "na", "nc", "ne", "nf", "ng", "ni", "nl", "no", "np", "nr",
  "nu", "nz", "om", "pa", "pe", "pf", "pg", "ph", "pk", "pl", "pm", "pn", "pr",
  "ps", "pt", "pw", "py", "qa", "re", "ro", "rs", "ru", "rw", "sa", "sb", "sc",
  "sd", "se", "sg", "sh", "si", "sj", "sk", "sl", "sm", "sn", "so", "sr", "ss",
  "st", "sv", "sx", "sy", "sz", "tc", "td", "tf", "tg", "th", "tj", "tk", "tl",
  "tm", "tn", "to", "tr", "tt", "tv", "tw", "tz", "ua", "ug", "um", "us", "uy",
  "uz", "va", "vc", "ve", "vg", "vi", "vn", "vu", "wf", "ws", "ye", "yt", "za",
  "zm", "zw",
];

/** The complete ISO country list — code + flag, ready for the scope menu. */
export const COUNTRIES: readonly Country[] = CODES.map((code) => ({
  code,
  flag: flagEmoji(code),
}));

/**
 * countryDisplayName — the localized region name for `code`, resolved via
 * Intl.DisplayNames. Falls back to the raw code when the runtime can't resolve
 * it (an unknown region, or an environment without Intl.DisplayNames) so the
 * control always renders something and never throws.
 */
export function countryDisplayName(code: string, locale: string): string {
  try {
    // fallback: "none" → an unresolvable region yields undefined (not the
    // runtime's "Unknown Region" placeholder), so we can degrade to the code.
    const display = new Intl.DisplayNames([locale], {
      type: "region",
      fallback: "none",
    });
    return display.of(code.toUpperCase()) ?? code;
  } catch {
    return code;
  }
}

/**
 * languageDisplayName — the localized name for an ISO-639-1 language code
 * (e.g. "fr" → "French" in en-US), used by the "Translated from {language}"
 * badge. Mirrors countryDisplayName: fallback "none" degrades an unresolvable
 * code to itself, and a structurally-invalid input is swallowed to the code.
 */
export function languageDisplayName(code: string, locale: string): string {
  try {
    const display = new Intl.DisplayNames([locale], {
      type: "language",
      fallback: "none",
    });
    return display.of(code) ?? code;
  } catch {
    return code;
  }
}


