/**
 * formatVolume — the ONE per-platform volume formatter for the collected-trends
 * board (#1144). This is the correctness seam: the volume unit lives HERE, never
 * in the term or in the numeric field, so a term can never render "views views"
 * and an unreported X term can never render a fabricated "0 posts".
 *
 * Unit per platform, rendered exactly once:
 *   google → searches   tiktok → views   x → posts   range → posts
 *
 * Values render COMPACT (200K / 2M / 19.3M, #2730 — matches CogOS 2.0) so a long
 * ranked list stays legible. Google's numbers are Google Trends' real search-
 * count BUCKETS (the actor reports "200K+"), so a google volume carries a
 * trailing "+"; every other platform's count is exact and gets no "+".
 *
 * The return is a discriminated union. A reported volume carries the fully
 * formatted "value unit" string. An UNREPORTED volume (X's real case,
 * `volume_reported=false` on the wire) carries no number at all —
 * `{ reported: false }` — so the caller renders the muted "not reported"
 * treatment instead of leaking the ignored raw volume.
 */

import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { localeForIntl, type Locale } from "@omnicore-platform/platform-chrome";
import type { TrendPlatform } from "../api/trends";

/** The formatted volume, or an explicit "not reported" marker. */
export type VolumeDisplay =
  | { readonly reported: true; readonly text: string }
  | { readonly reported: false };

/** The localized unit noun for a platform's volume. */
function unitFor(platform: TrendPlatform): string {
  switch (platform) {
    case "google":
      return m.monitor_trends_unit_searches();
    case "tiktok":
      return m.monitor_trends_unit_views();
    case "x":
    case "range":
      return m.monitor_trends_unit_posts();
  }
}

/**
 * Compact-notation formatters, memoized per Intl locale ("200K"/"200.000",
 * "2M"/"2 Mio.", "19.3M"/"19,3 Mio."). The compact abbreviation, grouping and
 * decimal separator are all locale-specific (#2988), so the formatter is built
 * for the caller's active locale rather than pinned to en-US — and cached, since
 * constructing an Intl.NumberFormat is not free on a long ranked list.
 *
 * The active Locale is routed through `localeForIntl` first (matching the
 * sibling country/date/number formatters), so the dev-only `xx-pseudo` sentinel
 * folds to `en-US` explicitly rather than relying on the engine's BCP-47
 * fallback. The 11 shipped locales are unaffected.
 */
const COMPACT_BY_LOCALE = new Map<string, Intl.NumberFormat>();

function compactFor(intlLocale: string): Intl.NumberFormat {
  let fmt = COMPACT_BY_LOCALE.get(intlLocale);
  if (fmt === undefined) {
    fmt = new Intl.NumberFormat(intlLocale, {
      notation: "compact",
      maximumFractionDigits: 1,
    });
    COMPACT_BY_LOCALE.set(intlLocale, fmt);
  }
  return fmt;
}

/**
 * formatVolume — build the display for one term's volume in the active `locale`.
 * When `volumeReported` is false the raw `volume` is ignored entirely and the
 * not-reported marker is returned; never a "0 <unit>". A reported volume renders
 * compact in the caller's locale; google's bucketed counts carry a trailing "+"
 * (e.g. "200K+ searches"), every other platform's exact count does not
 * (e.g. "19.3M views").
 */
export function formatVolume(
  platform: TrendPlatform,
  volume: number,
  volumeReported: boolean,
  locale: Locale,
): VolumeDisplay {
  if (!volumeReported) return { reported: false };
  const count = compactFor(localeForIntl(locale)).format(volume);
  // Google trending reports search-count BUCKETS ("200K+"), so its compact value
  // is a floor — the "+" says "at least". No other platform's count is bucketed.
  const bucketSuffix = platform === "google" ? "+" : "";
  return { reported: true, text: `${count}${bucketSuffix} ${unitFor(platform)}` };
}


