/**
 * imageProxy tests (extracted from WebResultCard for #2994 gallery reuse).
 *
 * The shared helper is the ONE place a Monitor thumbnail becomes a client-side
 * src: the raw provider/Google URL is only ever URL-encoded into the BFF
 * image-proxy route, never handed to the browser as a bare host (privacy /
 * no-hotlink requirement). Grid tiles (#2994), the image detail preview, and
 * the existing web result card all load through it.
 */
import { expect, test } from "vitest";
import { IMAGE_PROXY, proxiedThumbnail } from "./imageProxy";

test("IMAGE_PROXY is the BFF image-proxy route", () => {
  expect(IMAGE_PROXY).toBe("/api/v1/monitor/search/image-proxy");
});

test("proxiedThumbnail prefixes the proxy route and URL-encodes the raw URL", () => {
  const raw = "https://images.example.com/a b.jpg?x=1&y=2";
  const src = proxiedThumbnail(raw);

  expect(src).toBe(`${IMAGE_PROXY}?url=${encodeURIComponent(raw)}`);
  // The raw host never leaks into the src as a bare, un-encoded value: the
  // "://" and "&" that would make it a live cross-origin fetch are encoded.
  expect(src.startsWith(`${IMAGE_PROXY}?url=`)).toBe(true);
  expect(src).not.toContain("://images.example.com");
  expect(src).toContain(encodeURIComponent(raw));
});


--- frontends/monitor-mfe/src/lib/imageProxy.ts (19 lines) ---
/**
 * imageProxy — the ONE place a Monitor thumbnail becomes a client-side src.
 *
 * Extracted from WebResultCard (#1135) so the image gallery grid (#2994), the
 * image detail preview, and the existing web result card all load a thumbnail
 * through the same route. The raw provider/Google URL is ALWAYS fetched through
 * the BFF image-proxy (`/api/v1/monitor/search/image-proxy?url=<encoded>`),
 * never from the source host directly — a privacy / no-hotlink requirement, and
 * the CSP only allows the proxy origin.
 */

/** The BFF image-proxy route — the ONLY host the client loads a thumbnail from. */
export const IMAGE_PROXY = "/api/v1/monitor/search/image-proxy";

/** Build the proxied src for a thumbnail — the raw URL is only ever encoded, never a host. */
export function proxiedThumbnail(thumbnailUrl: string): string {
  return `${IMAGE_PROXY}?url=${encodeURIComponent(thumbnailUrl)}`;
}


