/**
 * languages — the curated "translate query into" list for the Search Translate
 * control (#2915), restoring CogOS-2.0's explicit-language search model.
 *
 * Each entry is an ISO-639-1 two-letter code, PLUS "prs" for Dari — which has
 * no 639-1 code but is a distinct written standard from Persian ("fa"), so the
 * two are listed SEPARATELY (a 2.0 requirement carried forward). Display names
 * resolve at RENDER time via Intl.DisplayNames (`languageDisplayName`), so the
 * same code shows the language's name in whatever locale the UI is in — never a
 * hardcoded English label that would go stale across the 11 locales. A manual
 * fallback covers the handful of codes a runtime's Intl data may not localize
 * (notably "prs").
 */

import { languageDisplayName } from "./countries";

/** One selectable "translate into" language: an ISO-639-1 code (or "prs"). */
export interface Language {
  /** ISO-639-1 code, lowercase (e.g. "es"); "prs" for Dari, which has none. */
  readonly code: string;
}

/**
 * Manual English display names for EVERY code in the list. These are the
 * guaranteed fallback when Intl.DisplayNames degrades to the raw code (fallback
 * "none") — which happens for codes a given runtime's ICU data can't localize.
 * Browsers resolve fewer codes than Node (e.g. "ba"=Bashkir, "bo"=Tibetan came
 * back bare in the browser but fine under vitest), so covering only "prs" left
 * real bare-code rows in the menu. Every code here therefore has a name; the
 * Intl-localized name is still preferred at render (see `languageOptionName`),
 * and this map is only consulted when the runtime can't localize the code.
 */
