  .trim()
  .split(/\s+/);

/** The curated language list — deduped, ready for the Translate menu. */
export const LANGUAGES: readonly Language[] = Array.from(new Set(RAW_CODES)).map(
  (code) => ({ code }),
);

/**
 * languageOptionName — the localized display name for a language `code` in
 * `locale`. Uses Intl.DisplayNames; when the runtime can't localize the code
 * (it degrades to the code itself), falls back to a manual English label if we
 * have one, else the raw code — so the menu always shows something readable and
 * never throws.
 */
export function languageOptionName(code: string, locale: string): string {
  const name = languageDisplayName(code, locale);
  if (name === code) return MANUAL_NAMES[code] ?? code;
  return name;
}


