/**
 * localeRegion — derive an ISO-3166-1 alpha-2 region from a BCP-47 locale tag
 * (#2915), used to default the Search Country filter to the user's own region.
 *
 * The returned code is LOWERCASE, matching the COUNTRIES table and Serper's
 * `gl` param (which lower-cases it anyway), so the derived default lines up
 * with a real option in the country picker.
 *
 * A tag that resolves to no single ISO country — most importantly the UN M.49
 * *area* tags like `es-419` (Spanish, Latin America), whose region is the
 * numeric "419" — returns `undefined`, so the caller falls back to Worldwide
 * (the cost-safe default) instead of inventing a bogus scope. An unparseable
 * or empty tag likewise returns `undefined` rather than throwing.
 */
export function localeRegion(locale: string): string | undefined {
  try {
    // maximize() fills in the likely region for a bare language tag ("en" →
    // en-Latn-US); a tag that already carries a region keeps it.
    const region = new Intl.Locale(locale).maximize().region;
    // Only a real ISO-3166-1 alpha-2 region qualifies — a numeric M.49 area
    // code (e.g. "419") is not a country the picker can select.
    return region !== undefined && /^[A-Z]{2}$/.test(region)
      ? region.toLowerCase()
      : undefined;
  } catch {
    return undefined;
  }
}


