import { getLocale } from "@omnicore-platform/platform-chrome";
import { codeFromName, isCountryCode, nameForCode } from "@omnicore-platform/ui";

/**
 * formatRegionLabel — blank → localized "Worldwide"; an ISO code or legacy
 * country name → the localized country name; an unrecognized value echoed back.
 */
export function formatRegionLabel(regionLabel: string): string {
  const trimmed = regionLabel.trim();
  if (trimmed === "") return m.monitor_trends_region_worldwide();

  const locale = getLocale();
  if (isCountryCode(trimmed)) return nameForCode(trimmed, locale);

  const code = codeFromName(trimmed);
  if (code) return nameForCode(code, locale);

  return regionLabel;
}


