/**
 * buildTrendSearchPath — the ONE builder for the "search this trend" deep-link
 * (ticket #1148). A trend row jumps into the Monitor Search route with the term
 * pre-filled and a source (web / news) pre-selected, so the seam that owns the
 * exact path shape lives HERE — never hand-assembled at each call site.
 *
 * The query is built with URLSearchParams so the term is safe to pass verbatim:
 * spaces encode as `+`, and `&` / `#` / unicode can never break out of the `q`
 * value into the path. The `q` and `source` param names and the `web` / `news`
 * source values are a CONTRACT consumed by SearchRoute — do not deviate.
 */

/** Which corpus the deep-linked Search should query. */
export type TrendSearchSource = "web" | "news";

/**
 * buildTrendSearchPath — build the router path that deep-links a pre-filled,
 * source-selected Monitor Search:
 *   /monitor/search?q=<encoded>&source=<source>
 * `term` is passed through verbatim as the `q` value (the route trims later).
 */
export function buildTrendSearchPath(
  term: string,
  source: TrendSearchSource,
): string {
  // The `/monitor` prefix is required: shell-mfe mounts this MFE at /monitor/*
  // and owns history, so a bare `/search` resolves at the shell root (no such
  // route) and bounces to `/`. Federated intra-MFE nav must carry the prefix.
  return `/monitor/search?${new URLSearchParams({ q: term, source }).toString()}`;
}


