/**
 * url.ts — URL validation for the Web Scraper input (ticket #1154).
 *
 * The scraper only fetches http:// and https:// pages, so the Scrape action
 * stays disabled and an inline validation message shows until the typed value
 * parses as one of those two schemes. Parsing goes through the WHATWG URL
 * constructor rather than a hand-rolled regex: it correctly rejects malformed
 * input, bare hosts, and every non-http(s) scheme (ftp:, javascript:, …) while
 * accepting real query strings and paths.
 */

/**
 * isHttpUrl — true only when `value` parses as an absolute http:// or https://
 * URL with a host. Surrounding whitespace is trimmed first (users paste padded
 * URLs). Any parse failure, missing host, or non-http(s) scheme returns false.
 */
export function isHttpUrl(value: string): boolean {
  const trimmed = value.trim();
  if (trimmed === "") return false;

  let url: URL;
  try {
    url = new URL(trimmed);
  } catch {
    return false;
  }

  if (url.host === "") return false;
  return url.protocol === "http:" || url.protocol === "https:";
}


