/**
 * useSession — fetches the user's session from /api/v1/session.
 *
 * Mirrors frontends/clio-mfe/src/lib/useSession.ts so monitor-mfe
 * can render the shared platform Topbar consistently whether it's
 * federated under shell-mfe (/monitor/*) or running standalone at
 * :5180. The shell-bff /api/v1/session endpoint returns user_id /
 * org_id / roles[] / email derived from the JWT claims; we unwrap the
 * standard {data, error} envelope here so callers see a flat Session.
 *
 * Returns:
 *   - { state: "loading" } while the fetch is in flight
 *   - { state: "ready", session } on success
 *   - { state: "error", message } on rejection
 */

import { useEffect, useState } from "react";

export interface Session {
  user_id: string;
  org_id: string;
  roles: string[];
  email: string;
}

export type SessionState =
  | { state: "loading" }
  | { state: "ready"; session: Session }
  | { state: "error"; message: string };

let cached: Session | null = null;
let inFlight: Promise<Session> | null = null;

async function fetchSession(): Promise<Session> {
  if (cached) return cached;
  if (inFlight) return inFlight;
  inFlight = fetch("/api/v1/session", { credentials: "include" })
    .then(async (r) => {
      const body = await r.json();
      if (!r.ok) {
        throw new Error(body?.error ?? `HTTP ${r.status}`);
      }
      const s = body.data as Session;
      cached = s;
      return s;
    })
    // #2413 (P1-34): clear the in-flight singleton on BOTH success and
    // failure so a transient error doesn't poison the cache with a
    // rejected promise for the process lifetime — a later mount must be
    // able to re-fetch and recover. Mirrors ask-mfe's fixed copy.
    .finally(() => {
      inFlight = null;
    });
  return inFlight;
}

export function useSession(): SessionState {
  const [state, setState] = useState<SessionState>({ state: "loading" });

  useEffect(() => {
    let alive = true;
    fetchSession()
      .then((session) => {
        if (alive) setState({ state: "ready", session });
      })
      .catch((err: unknown) => {
        const message = err instanceof Error ? err.message : "Session error";
        if (alive) setState({ state: "error", message });
      });
    return () => {
      alive = false;
    };
  }, []);

  return state;
}



