/**
 * nextCollection — the client-derived, PRESENTATIONAL next-collection estimate
 * for the Trends surface (#1146).
 *
 * No scheduler or collector exists yet (#2286/#2730), so this is deliberately
 * an ESTIMATE, not a promise a run fired: given a check frequency and a "from"
 * instant (defaulting to now), it projects one cadence interval forward and
 * formats a local wall-clock time. The Edit dialog and the save banner both use
 * it so the displayed "next collection" time updates immediately when the user
 * changes the frequency — the honest way to satisfy that AC without faking a run.
 *
 * An unknown frequency falls back to the hourly interval — the safe default a
 * monitor row missing a recognized cadence would carry.
 */

const FREQUENCY_MINUTES: Record<string, number> = {
  "15m": 15,
  hourly: 60,
  "6h": 360,
  daily: 1440,
};

/** The projected next-collection instant = `from` + one cadence interval. */
export function nextCollectionAt(
  frequency: string,
  from: Date = new Date(),
): Date {
  const minutes = FREQUENCY_MINUTES[frequency] ?? 60;
  return new Date(from.getTime() + minutes * 60_000);
}

/** A localized wall-clock time (e.g. "3:45 PM") for the projected instant. */
export function formatNextCollection(
  frequency: string,
  from: Date = new Date(),
): string {
  return nextCollectionAt(frequency, from).toLocaleTimeString(undefined, {
    hour: "numeric",
    minute: "2-digit",
  });
}


