/**
 * relativeExecutedAt — a localized "last executed" phrase for a saved query
 * (#1137). "" / unparseable ⇒ "Never run"; under a minute ⇒ "just now"; older
 * ⇒ an Intl.RelativeTimeFormat phrase from the largest sensible unit, so a row
 * reads "2 hours ago" / "yesterday" / "3 weeks ago" without a bespoke formatter.
 */

import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

export function relativeExecutedAt(
  iso: string,
  locale: string,
  now: Date = new Date(),
): string {
  if (iso === "") return m.monitor_saved_query_last_run_never();
  const then = new Date(iso);
  if (Number.isNaN(then.getTime())) return m.monitor_saved_query_last_run_never();

  const seconds = Math.round((now.getTime() - then.getTime()) / 1000);
  if (seconds < 60) return m.monitor_saved_query_last_run_just_now();

  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });
  const minutes = Math.round(seconds / 60);
  if (minutes < 60) return rtf.format(-minutes, "minute");
  const hours = Math.round(minutes / 60);
  if (hours < 24) return rtf.format(-hours, "hour");
  const days = Math.round(hours / 24);
  if (days < 7) return rtf.format(-days, "day");
  const weeks = Math.round(days / 7);
  if (weeks < 5) return rtf.format(-weeks, "week");
  const months = Math.round(days / 30);
  if (months < 12) return rtf.format(-months, "month");
  const years = Math.round(days / 365);
  return rtf.format(-years, "year");
}


