/**
 * translateLocales — the 11 platform target locales plus the display helpers the
 * Translate split-button and translation panel share (ticket #1157).
 *
 * Language display names are LOCALIZED via Intl.DisplayNames keyed on the app's
 * CURRENT locale — never an i18n key — so "es-419" renders as "Latin American
 * Spanish" in an English UI and its own localized name elsewhere. The chip shows
 * a short code; `isPageLanguage` flags the scraped page's own language in the
 * list so the user can see the source.
 */

/**
 * The platform's 11 supported locales, in the platform's canonical order. These
 * are the targets the "Read in" popover offers — BCP-47 tags matching the
 * frontends/messages/<locale> message bundles.
 */
export const TARGET_LOCALES = [
  "en-US",
  "en-GB",
  "en-AU",
  "ar-AE",
  "de-DE",
  "es-419",
  "fr-CA",
  "ja-JP",
  "mn-MN",
  "tl-PH",
  "zh-Hans",
] as const;

/** A BCP-47 tag from {@link TARGET_LOCALES}. */
export type TargetLocale = (typeof TARGET_LOCALES)[number];

/**
 * TRANSLATE_MAX_WORDS — the word-count ceiling above which the UI declines to
 * translate a page in full. ~2000 words ≈ ~12k chars ≈ ~90s translate; the
 * monitor-svc safety cap is 16k chars, so a longer Default-engine page would
 * time out the call. Over this, we show an honest notice and nudge the user to
 * the Reader engine instead of firing a doomed request.
 */
export const TRANSLATE_MAX_WORDS = 2000;

/**
 * resolveDefaultTarget — the target locale the split-button defaults to. Prefer
 * the app's current UI locale when it is one of the platform targets (so an
 * English user's default target is en-US, a German user's is de-DE, etc.);
 * otherwise fall back to the first platform locale. Avoids seeding a default
 * that would translate a page into a language the user didn't ask for.
 */
export function resolveDefaultTarget(appLocale: string): TargetLocale {
  return (TARGET_LOCALES as readonly string[]).includes(appLocale)
    ? (appLocale as TargetLocale)
    : TARGET_LOCALES[0];
}

/**
 * displayLanguageName — the localized language name for `bcp47`, rendered in
 * `displayLocale` (the active app locale). Falls back to the raw tag when Intl
 * cannot resolve a name (or throws on a malformed tag) so the UI never renders
 * "undefined".
 */
export function displayLanguageName(bcp47: string, displayLocale: string): string {
  try {
    // fallback:"none" so an unresolved (but well-formed) tag returns undefined —
    // we then fall back to the raw tag ourselves. A malformed tag throws and is
    // caught below. Both fall-backs are exercised by the unit tests.
    const name = new Intl.DisplayNames([displayLocale], {
      type: "language",
      fallback: "none",
    }).of(bcp47);
    return name ?? bcp47;
  } catch {
    return bcp47;
  }
}

/** The base (primary) language subtag, region/script stripped. */
function baseSubtag(bcp47: string): string {
  return bcp47.replace(/-.*$/, "");
}

/**
 * shortCode — the region-stripped, uppercased primary language subtag (e.g.
 * "es-419" → "ES", "zh-Hans" → "ZH"). Shown on the split-button chip as a
 * compact hint of the current target; the popover row carries the full name.
 */
export function shortCode(bcp47: string): string {
  return baseSubtag(bcp47).toUpperCase();
}

/**
 * isPageLanguage — whether `locale`'s base language subtag matches the scraped
 * page's detected `pageLanguage` (case-insensitive base compare). Used to flag
 * the source language in the target list. An empty page language never matches.
 */
export function isPageLanguage(pageLanguage: string, locale: string): boolean {
  if (pageLanguage === "") return false;
  return baseSubtag(pageLanguage).toLowerCase() === baseSubtag(locale).toLowerCase();
}


